func (s Service) execute(client Client, opts ExecuteOptions) (ExecuteResult, error) {
    ctx := opts.Context
    if ctx == nil {
        ctx = context.Background()
    }
    task, err := FindTask(opts.TaskID)
    if err != nil {
        return ExecuteResult{}, err
    }

    result := ExecuteResult{
        TaskID:    task.ID,
        TaskName:  task.Name,
        Status:    "running",
        Verified:  task.Verified,
        StartedAt: now(),
        progress:  opts.Progress,
    }
    result.Checkpoint("开始执行")

    if task.UsesPVE {
        result, err = s.executePVEDailyScaffold(ctx, task, result, opts)
    } else {
        switch task.ID {
        case "friendship_star_gift":
            result, err = s.executeFriendship(ctx, client, result, timeout)
        case "six_realm_palace_sweep":
            result, err = s.executeSixRealm(ctx, client, result, opts.Params, timeout)
        default:
            err = fmt.Errorf("daily task executor not implemented: %s", task.ID)
        }
    }

    result.EndedAt = now()
    return result, err
}

const battleRequestQueues = new Map<string, Promise<void>>();

async function runSerializedBattleRequest<T>(instanceId: string, task: () => Promise<T>): Promise<T> {
  const key = instanceId || 'default';
  const previous = battleRequestQueues.get(key) ?? Promise.resolve();
  let release!: () => void;
  const current = new Promise<void>((resolve) => {
    release = resolve;
  });
  const queued = previous.catch(() => undefined).then(() => current);
  battleRequestQueues.set(key, queued);
  await previous.catch(() => undefined);
  try {
    return await task();
  } finally {
    release();
    if (battleRequestQueues.get(key) === queued) {
      battleRequestQueues.delete(key);
    }
  }
}

export const useConnectionInstancesStore = defineStore('connectionInstances', {
  state: () => ({
    toolUserId: 'local',
    defaultInstanceId: 'default',
    activeInstanceId: loadStoredActiveInstanceId('local'),
    instances: [] as ConnectionInstanceDTO[],
    loading: false,
    operating: false,
    error: '',
