  getters: {
    activeInstance: (state): ConnectionInstanceDTO | null =>
      state.instances.find((instance) => instance.id === state.activeInstanceId) ??
      state.instances.find((instance) => instance.id === state.defaultInstanceId) ??
      state.instances[0] ??
      null,
  },
